import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor,
                                          torch::Tensor positive,
                                          torch::Tensor negative,
                                          double margin);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
#define THREADS 512
#define REDUCE_THREADS 256
__global__ void triplet_margin_loss_row_kernel(
    const float* __restrict__ anchor,
    const float* __restrict__ positive,
    const float* __restrict__ negative,
    float* __restrict__ row_loss,
    int batch, int dim, float margin)
{
  int row = blockIdx.x;
  if (row >= batch) return;
  int tid = threadIdx.x;
  int nthreads = blockDim.x;
  // Vectorized (float4) access to global memory for coalesced, wide loads
  const float* rowA = anchor + (int64_t)row * dim;
  const float* rowP = positive + (int64_t)row * dim;
  const float* rowN = negative + (int64_t)row * dim;
  int vec_dim = dim / 4;
  const float4* mA4 = reinterpret_cast<const float4*>(rowA);
  const float4* mP4 = reinterpret_cast<const float4*>(rowP);
  const float4* mN4 = reinterpret_cast<const float4*>(rowN);
  float sum_pos = 0.0f;
  float sum_neg = 0.0f;
  for (int i = tid; i < vec_dim; i += nthreads) {
    float4 a4 = mA4[i];
    float4 p4 = mP4[i];
    float4 n4 = mN4[i];
    float dp0 = a4.x - p4.x;
    float dp1 = a4.y - p4.y;
    float dp2 = a4.z - p4.z;
    float dp3 = a4.w - p4.w;
    float dn0 = a4.x - n4.x;
    float dn1 = a4.y - n4.y;
    float dn2 = a4.z - n4.z;
    float dn3 = a4.w - n4.w;
    sum_pos += dp0 * dp0 + dp1 * dp1 + dp2 * dp2 + dp3 * dp3;
    sum_neg += dn0 * dn0 + dn1 * dn1 + dn2 * dn2 + dn3 * dn3;
  }
  // Tail elements (dim not divisible by 4)
  for (int i = vec_dim * 4 + tid; i < dim; i += nthreads) {
    float a = rowA[i];
    float p = rowP[i];
    float n = rowN[i];
    float dp = a - p;
    float dn = a - n;
    sum_pos += dp * dp;
    sum_neg += dn * dn;
  }
  // Warp-level reduction using shuffle instructions to avoid full shared-memory tree reduction
  unsigned mask = 0xffffffffu;
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    sum_pos += __shfl_down_sync(mask, sum_pos, offset);
    sum_neg += __shfl_down_sync(mask, sum_neg, offset);
  }
  int lane_id = tid & 31;
  int warp_id = tid >> 5;
  int num_warps = (nthreads + 31) >> 5;
  __shared__ float warp_pos[THREADS / 32];
  __shared__ float warp_neg[THREADS / 32];
  if (lane_id == 0) {
    warp_pos[warp_id] = sum_pos;
    warp_neg[warp_id] = sum_neg;
  }
  __syncthreads();
  if (warp_id == 0) {
    float final_pos = (lane_id < num_warps) ? warp_pos[lane_id] : 0.0f;
    float final_neg = (lane_id < num_warps) ? warp_neg[lane_id] : 0.0f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      final_pos += __shfl_down_sync(mask, final_pos, offset);
      final_neg += __shfl_down_sync(mask, final_neg, offset);
    }
    if (lane_id == 0) {
      float d_pos = sqrtf(final_pos);
      float d_neg = sqrtf(final_neg);
      float loss = d_pos - d_neg + margin;
      loss = loss > 0.0f ? loss : 0.0f;
      // Store the raw per-row loss; the final mean reduction is
      // performed by a dedicated low-contention reduction kernel
      // instead of having every one of the 'batch' blocks issue an
      // atomicAdd on the same global address (which serializes).
      row_loss[row] = loss;
    }
  }
}
// Second-stage reduction: sums the per-row losses computed above into a
// single mean value using an intra-block tree/shuffle reduction
// followed by only a handful of atomicAdd operations (one per
// reduction block instead of one per row), greatly reducing atomic
// contention versus a single global atomic per row.
__global__ void triplet_margin_loss_reduce_kernel(
    const float* __restrict__ row_loss,
    float* __restrict__ loss_out,
    int batch)
{
  __shared__ float sdata[REDUCE_THREADS];
  int tid = threadIdx.x;
  int idx = blockIdx.x * blockDim.x + tid;
  int stride = blockDim.x * gridDim.x;
  float sum = 0.0f;
  for (int i = idx; i < batch; i += stride) {
    sum += row_loss[i];
  }
  sdata[tid] = sum;
  __syncthreads();
  for (int s = blockDim.x / 2; s > 32; s >>= 1) {
    if (tid < s) sdata[tid] += sdata[tid + s];
    __syncthreads();
  }
  if (tid < 32) {
    float v = sdata[tid];
    if (blockDim.x >= 64) v += sdata[tid + 32];
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      v += __shfl_down_sync(mask, v, offset);
    }
    if (tid == 0) {
      atomicAdd(loss_out, v / (float)batch);
    }
  }
}
torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor,
                                          torch::Tensor positive,
                                          torch::Tensor negative,
                                          double margin) {
  TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(),
              "All inputs must be CUDA tensors");
  TORCH_CHECK(anchor.scalar_type() == at::kFloat &&
              positive.scalar_type() == at::kFloat &&
              negative.scalar_type() == at::kFloat,
              "All inputs must be float32");
  TORCH_CHECK(anchor.dim() == 2 && positive.dim() == 2 && negative.dim() == 2,
              "Inputs must be 2D [batch, dim]");
  TORCH_CHECK(anchor.sizes() == positive.sizes() && anchor.sizes() == negative.sizes(),
              "All inputs must have the same shape");
  auto a_c = anchor.contiguous();
  auto p_c = positive.contiguous();
  auto n_c = negative.contiguous();
  int batch = (int)a_c.size(0);
  int dim   = (int)a_c.size(1);
  auto row_loss = torch::empty({batch}, a_c.options());
  auto loss = torch::zeros({}, a_c.options());
  dim3 block(THREADS);
  dim3 grid(batch);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  triplet_margin_loss_row_kernel<<<grid, block, 0, stream>>>(
      a_c.data_ptr<float>(),
      p_c.data_ptr<float>(),
      n_c.data_ptr<float>(),
      row_loss.data_ptr<float>(),
      batch, dim, (float)margin
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "triplet_margin_loss_row_kernel launch failed: ", cudaGetErrorString(err));
  int reduce_blocks = (batch + REDUCE_THREADS - 1) / REDUCE_THREADS;
  reduce_blocks = reduce_blocks > 256 ? 256 : reduce_blocks;
  if (reduce_blocks < 1) reduce_blocks = 1;
  triplet_margin_loss_reduce_kernel<<<reduce_blocks, REDUCE_THREADS, 0, stream>>>(
      row_loss.data_ptr<float>(),
      loss.data_ptr<float>(),
      batch
  );
  err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "triplet_margin_loss_reduce_kernel launch failed: ", cudaGetErrorString(err));
  return loss;
}
"""

triplet_ext = load_inline(
    name="cute_triplet_margin_loss_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["triplet_margin_loss_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Computes Triplet Margin Loss (p=2, reduction='mean') using a single
    fused custom CUDA/CUTE kernel.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)
        self._ext = triplet_ext

    def forward(self, anchor: torch.Tensor, positive: torch.Tensor, negative: torch.Tensor) -> torch.Tensor:
        return self._ext.triplet_margin_loss_forward(
            anchor.contiguous(),
            positive.contiguous(),
            negative.contiguous(),
            self.margin,
        )

